package dustin.cex.domains.kyc;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dustin.cex.domains.auth.model.entity.*;
import dustin.cex.domains.cdd.EddService;
import dustin.cex.domains.edd.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.dao.DataAccessException;
import org.springframework.http.MediaType;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

/** 독립 결정의 사실만 공개하고 내부 메모·기관 판단·거래 권한을 전달하지 않는지 검증한다. */
class CustomerReviewReplyIntegrationTest extends ExitTestSupport {
    @Autowired dustin.cex.domains.cdd.CddCrypto fingerprints;
    @Autowired CustomerExitReviewService requests;@Autowired CustomerReviewNoteService notes;@Autowired CustomerReviewReplyService replies;
    CustomerExitReviewService.Receipt receipt;CustomerReviewNoteService.Note note;
    @BeforeEach void prepare() throws Exception {initiated();receipt=requests.submit(customer.getId(),sid,UUID.randomUUID(),new CustomerExitReviewService.Submission("고객 비공개 요청"));requests.inspect(maker.user().getId(),maker.sid(),receipt.id());note=notes.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"외부 공개하면 안 되는 내부 비공개 메모"));}
    CustomerReviewReplyService.Reply reply(UUID key){return replies.record(maker.user().getId(),maker.sid(),receipt.id(),key,note.id());}
    long count(){return jdbc.queryForObject("SELECT count(*) FROM customer_exit_review_replies WHERE request_id=?",Long.class,receipt.id());}
    @Test void activeExitProducesOnlyControlledHistoricalStatus() throws Exception {var result=reply(UUID.randomUUID());assertEquals(CustomerReviewReplyService.Status.EXIT_INITIATION_ACTIVE,result.status());String raw=json.writeValueAsString(result);for(String word:List.of("비공개","noteId","actorId","basisId","INVESTIGATING","payloadHash","userId"))assertFalse(raw.contains(word));assertEquals(List.of(result),replies.own(customer.getId(),sid,receipt.id(),0));assertEquals(1,active());assertEquals("RECEIVED",requests.own(customer.getId(),sid,receipt.id()).status());blocked();
        // 이전 서버가 다른 안내 문구를 서명한 표본이다. 현재 템플릿으로 과거 기록을 다시 쓰지 않아야 한다.
        var stored=jdbc.queryForMap("SELECT * FROM customer_exit_review_replies WHERE id=?",result.id());var payload=(tools.jackson.databind.node.ObjectNode)json.readTree((String)stored.get("payload"));UUID historic=UUID.randomUUID();payload.put("id",historic.toString());payload.put("sequence",2);payload.put("message","당시 서버가 제공한 고객 안내 문구");String rawHistoric=json.writeValueAsString(payload);
        jdbc.update("INSERT INTO customer_exit_review_replies(id,request_id,sequence,actor_id,request_key,note_id,note_sequence,payload,content_mac,fingerprint_key_id) VALUES(?,?,2,?,?,?,?,?,?,?)",historic,receipt.id(),maker.user().getId(),UUID.randomUUID(),note.id(),note.sequence(),rawHistoric,fingerprints.fingerprint("customer-review-public-reply",rawHistoric),fingerprints.keyId());
        assertEquals("당시 서버가 제공한 고객 안내 문구",replies.own(customer.getId(),sid,receipt.id(),0).getFirst().message());
}
    @Test void rescindedStatusRequiresActualApprovedIndependentRescission() throws Exception {approveWithdrawal(withdraw(UUID.randomUUID()));var result=reply(UUID.randomUUID());assertEquals(CustomerReviewReplyService.Status.EXIT_INITIATION_RESCINDED,result.status());assertEquals(0,active());blocked();}
    @Test void pendingAndRejectedRescissionDoNotPublishRescindedStatus() throws Exception {var r=withdraw(UUID.randomUUID());assertEquals(CustomerReviewReplyService.Status.EXIT_INITIATION_ACTIVE,reply(UUID.randomUUID()).status());withdrawDecide(r,false,withdrawalProof(independent,r,false));assertEquals(CustomerReviewReplyService.Status.EXIT_INITIATION_ACTIVE,reply(UUID.randomUUID()).status());assertEquals(1,active());}
    @Test void oldRequestIsNotConfusedWithAReinitiatedExit() throws Exception {UUID exit=original.payload().id();approveWithdrawal(withdraw(UUID.randomUUID()));referral=propose(EddService.Finding.COMPLIANCE_ESCALATION);decide(referral,true,proof(checker,referral,true));original=request(UUID.randomUUID(),facts());reportDecide(original,true,reportProof(checker,original,true));assertNotEquals(exit,original.payload().id());assertEquals(CustomerReviewReplyService.Status.EXIT_INITIATION_RESCINDED,reply(UUID.randomUUID()).status());assertEquals(1,active());}
    @Test void sameKeyReplayPreservesOldStatusAfterActualStateChange() throws Exception {UUID key=UUID.randomUUID();var old=reply(key);approveWithdrawal(withdraw(UUID.randomUUID()));assertEquals(old,reply(key));assertEquals(CustomerReviewReplyService.Status.EXIT_INITIATION_RESCINDED,reply(UUID.randomUUID()).status());assertEquals(2,count());}
    @Test void staleInternalNoteCannotBeUsedForNewReplyButOldKeyStillReplays() throws Exception {UUID key=UUID.randomUUID();var old=reply(key);var next=notes.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.ADDITIONAL_CHECK_REQUIRED,"다음 내부 메모"));assertThrows(ResponseStatusException.class,()->reply(UUID.randomUUID()));assertEquals(old,reply(key));assertThrows(ResponseStatusException.class,()->replies.record(maker.user().getId(),maker.sid(),receipt.id(),key,next.id()));assertNotNull(replies.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),next.id()));}
    @Test void anotherPersonsViewCannotAuthorizeReply() throws Exception {assertThrows(ResponseStatusException.class,()->replies.record(checker.user().getId(),checker.sid(),receipt.id(),UUID.randomUUID(),note.id()));requests.inspect(checker.user().getId(),checker.sid(),receipt.id());assertNotNull(replies.record(checker.user().getId(),checker.sid(),receipt.id(),UUID.randomUUID(),note.id()));}
    @Test void missingAndForeignNoteIdsAreRejected() throws Exception {assertThrows(ResponseStatusException.class,()->replies.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),null));assertThrows(ResponseStatusException.class,()->replies.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),UUID.randomUUID()));assertEquals(0,count());}
    @Test void concurrentRepliesKeepDistinctLogicalOrder() throws Exception {var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{start.await();return reply(UUID.randomUUID());});var b=pool.submit(()->{start.await();return reply(UUID.randomUUID());});start.countDown();assertNotEquals(a.get(10,TimeUnit.SECONDS).id(),b.get(10,TimeUnit.SECONDS).id());assertEquals(List.of(1L,2L),jdbc.queryForList("SELECT sequence FROM customer_exit_review_replies WHERE request_id=? ORDER BY sequence",Long.class,receipt.id()));}finally{pool.shutdownNow();}}
    @Test void tenRepliesAndIdempotentReplayRespectDailyLimit() throws Exception {UUID key=UUID.randomUUID();var first=reply(key);for(int i=1;i<10;i++)reply(UUID.randomUUID());assertEquals(429,assertThrows(ResponseStatusException.class,()->reply(UUID.randomUUID())).getStatusCode().value());assertEquals(first,reply(key));}
    @Test void auditFailureRollsBackReplyAndSameKeyCanRetry() throws Exception {UUID key=UUID.randomUUID();doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_REVIEW_REPLY_RECORDED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->reply(key));assertEquals(0,count());reset(audit);assertNotNull(reply(key));assertEquals(1,count());}
    @Test void customerCannotReadOtherCustomersReplies() throws Exception {reply(UUID.randomUUID());var other=users.saveAndFlush(User.builder().email(UUID.randomUUID()+"@test.invalid").passwordHash(hash).build());var token=tokens.saveAndFlush(RefreshToken.builder().userId(other.getId()).tokenHash(UUID.randomUUID().toString()).expiresAt(LocalDateTime.now().plusHours(1)).build());assertThrows(ResponseStatusException.class,()->replies.own(other.getId(),token.getSessionId(),receipt.id(),0));assertThrows(ResponseStatusException.class,()->replies.assigned(independent.user().getId(),independent.sid(),receipt.id(),0));}
    @Test void customerReadAuditFailureDoesNotReturnReplyList() throws Exception {reply(UUID.randomUUID());doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_REVIEW_REPLIES_OWN"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->replies.own(customer.getId(),sid,receipt.id(),0));reset(audit);assertEquals(1,replies.own(customer.getId(),sid,receipt.id(),0).size());}
    @Test void immutableReplyAndCopiedPayloadIntegrityAreEnforced() throws Exception {var result=reply(UUID.randomUUID());for(String sql:List.of("UPDATE customer_exit_review_replies SET id=id","DELETE FROM customer_exit_review_replies","TRUNCATE customer_exit_review_replies"))assertThrows(DataAccessException.class,()->jdbc.execute(sql));jdbc.update("INSERT INTO customer_exit_review_replies(id,request_id,sequence,actor_id,request_key,note_id,note_sequence,payload,content_mac,fingerprint_key_id) SELECT ?,request_id,2,actor_id,?,note_id,note_sequence,payload,content_mac,fingerprint_key_id FROM customer_exit_review_replies WHERE id=?",UUID.randomUUID(),UUID.randomUUID(),result.id());assertThrows(IllegalStateException.class,()->replies.own(customer.getId(),sid,receipt.id(),0));}
    @ParameterizedTest @ValueSource(strings={"disabled","expired","recovery","identity"})
    void currentStaffAuthorityIsRequired(String how) throws Exception {var u=users.findById(maker.user().getId()).orElseThrow();switch(how){case "disabled"->u.setEnabled(false);case "expired"->u.setOperatorAccessExpiresAt(Instant.now().minusSeconds(1));case "recovery"->u.setOperatorRecoveryRequestId(UUID.randomUUID());case "identity"->u.setOperatorPersonId(UUID.randomUUID());default->throw new AssertionError();}users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->reply(UUID.randomUUID()));}
    @Test void oldMfaAndRevokedCustomerSessionAreRejected() throws Exception {var t=tokens.findBySessionId(maker.sid()).orElseThrow();t.setMfaVerifiedAt(LocalDateTime.now().minusMinutes(6));tokens.saveAndFlush(t);assertThrows(ResponseStatusException.class,()->reply(UUID.randomUUID()));t=tokens.findBySessionId(sid).orElseThrow();t.setRevoked(true);tokens.saveAndFlush(t);assertThrows(ResponseStatusException.class,()->replies.own(customer.getId(),sid,receipt.id(),0));}
    @Test void badPageKeyAndAmbientTransactionAreRejected() throws Exception {assertThrows(ResponseStatusException.class,()->reply(null));assertThrows(ResponseStatusException.class,()->replies.own(customer.getId(),sid,receipt.id(),-1));assertThrows(org.springframework.transaction.IllegalTransactionStateException.class,()->new TransactionTemplate(manager).execute(t->reply(UUID.randomUUID())));}
    @Test void httpOnlyAssignedStaffCanRecordAndCustomerReadsSafeReply() throws Exception {String path="/api/admin/compliance/customer-review-requests/"+receipt.id()+"/replies";mvc.perform(post(path).header("Authorization","Bearer "+maker.access()).header("Idempotency-Key",UUID.randomUUID()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(new CustomerReviewReplyController.Request(note.id())))).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("EXIT_INITIATION_ACTIVE"));String body=mvc.perform(get("/api/customer/relationship/review-requests/"+receipt.id()+"/replies").header("Authorization","Bearer "+customerAccess)).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store"))).andReturn().getResponse().getContentAsString();assertFalse(body.contains("noteId"));assertFalse(body.contains("비공개"));mvc.perform(get(path).header("Authorization","Bearer "+independent.access())).andExpect(status().isNotFound());mvc.perform(post(path).header("Authorization","Bearer "+customerAccess).header("Idempotency-Key",UUID.randomUUID()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(new CustomerReviewReplyController.Request(note.id())))).andExpect(status().isForbidden());}
}
